r=player.Character local hum=char and char:FindFirstChildOfClass("Humanoid")if hum and hum.Health<hum.MaxHealth and hum.Health>0 then hum.Health=hum.MaxHealth end end end)task.spawn(function()while _G.GodModeActive do local char=player.Character local hum=char and char:WaitForChild("Humanoid",5)local root=char and char:WaitForChild("HumanoidRootPart",5)if hum and root then local diedConn local lastLoc=root.CFrame diedConn=hum.Died:Connect(function()if _G.GodModeActive then Window:Notify({Title="系統提示",Content="正在原地強制復活...",Duration=2})local newChar=player.CharacterAdded:Wait()local nRoot=newChar:WaitForChild("HumanoidRootPart",5)local nHum=newChar:WaitForChild("Humanoid",5)if nRoot and nHum then task.wait(0.1)nRoot.CFrame=lastLoc nHum.Health=nHum.MaxHealth end end diedConn:Disconnect()end)end player.CharacterAdded:Wait()end end)Window:Notify({Title="無敵系統",Content="雙重鎖定防線已啟動",Duration=3})end})Main:CreateInput({Name="修改移動速度 (極速鎖定)",PlaceholderText="請輸入數字 (例如: 100)",RemoveTextAfterFocusLost=false,Callback=function(Text)local num=tonumber(Text)if num then local player=game.Players.LocalPlayer task.spawn(function()while task.wait()do local char=player.Character local hum=char and char:FindFirstChildOfClass("Humanoid")if hum then hum.WalkSpeed=num local root=char:FindFirstChild("HumanoidRootPart")if hum.MoveDirection.Magnitude>0 and root then root.Velocity=root.Velocity.Unitnum end end end end)Window:Notify({Title="成功",Content="速度已極速鎖定為: "..Text,Duration=2})end end})Main:CreateSlider({Name="角色體型大小調整",Range={0.2,5},Increment=0.1,CurrentValue=1,Callback=function(Value)local char=game.Players.LocalPlayer.Character if char and char:FindFirstChildOfClass("Humanoid")then pcall(function()char:ScaleTo(Value)end)end end})Items:CreateButton({Name="獲得必殺全維迴旋碎體神劍",Callback=function()local player=game.Players.LocalPlayer local bp=player:FindFirstChild("Backpack")or player:WaitForChild("Backpack",5)if not bp then return end local Sword=Instance.new("Tool")Sword.Name="必殺一體巨刃"Sword.Require